              "curl": "curl -X POST \"https://api.nextmoe.dev/v2/me/discussions\" \\\n  -H \"Authorization: Bearer <ACCESS_TOKEN>\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"anchor_id\":\"1\",\"anchor_kind\":\"string\",\"body\":\"string\"}'"
